{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.6.6","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[{"sourceType":"datasetVersion","sourceId":6325826}],"isInternetEnabled":true,"language":"python","sourceType":"notebook","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"source":"<a href=\"https://www.kaggle.com/code/echogooglitch/notebookb2fec1070e?scriptVersionId=354650330\" target=\"_blank\"><img align=\"left\" alt=\"Kaggle\" title=\"Open in Kaggle\" src=\"https://kaggle.com/static/images/open-in-kaggle.svg\"></a>","metadata":{},"cell_type":"markdown"},{"cell_type":"code","source":"# This Python 3 environment comes with many helpful analytics libraries installed\n# It is defined by the kaggle/python Docker image: https://github.com/kaggle/docker-python\n# For example, here's several helpful packages to load\n\nimport numpy as np # linear algebra\nimport pandas as pd # data processing, CSV file I/O (e.g. pd.read_csv)\n\n# Input data files are available in the read-only \"../input/\" directory\n# For example, running this (by clicking run or pressing Shift+Enter) will list all files under the input directory\n\nimport os\nfor dirname, _, filenames in os.walk('/kaggle/input'):\n    for filename in filenames:\n        print(os.path.join(dirname, filename))\n\n# You can write up to 20GB to the current directory (/kaggle/working/) that gets preserved as output when you create a version using \"Save & Run All\" \n# You can also write temporary files to /kaggle/temp/, but they won't be saved outside of the current session\n\n# Use the kagglehub client library to attach Kaggle resources like competitions, datasets, and models to your session\n# Learn more about kagglehub: https://github.com/Kaggle/kagglehub/blob/main/README.md\n\nimport kagglehub\n# kagglehub.dataset_download('<owner>/<dataset-slug>')","metadata":{"_uuid":"8f2839f25d086af736a60e9eeb907d3b93b6e0e5","_cell_guid":"b1076dfc-b9ad-4769-8c92-a6c4dae69d19","trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"\"\"\"BUSI-corrected: benign vs malignant ultrasound classifier (PyTorch, DenseNet121).\npip install kagglehub torch torchvision scikit-learn pillow imagehash\n\"\"\"\nimport os, glob, random, numpy as np, torch, torch.nn as nn\nimport kagglehub, imagehash\nfrom PIL import Image\nfrom torch.utils.data import Dataset, DataLoader\nfrom torchvision import models, transforms as T\nfrom sklearn.model_selection import StratifiedGroupKFold\nfrom sklearn.metrics import roc_auc_score, confusion_matrix, classification_report\n\nSEED, EPOCHS, BS, LR = 42, 15, 16, 1e-4\nrandom.seed(SEED); np.random.seed(SEED); torch.manual_seed(SEED)\ndev = \"cuda\" if torch.cuda.is_available() else (\"mps\" if torch.backends.mps.is_available() else \"cpu\")\n\npath = kagglehub.dataset_download(\"jarintasnim090/busi-corrected\")\nprint(\"Path to dataset files:\", path)\n\n# Collect images; skip masks; label from class folder name (benign=0, malignant=1)\nfiles, labels = [], []\nfor p in glob.glob(os.path.join(path, \"**\", \"*.*\"), recursive=True):\n    low = p.lower()\n    if not low.endswith((\".png\", \".jpg\", \".jpeg\")) or \"mask\" in low: continue\n    parts = [s.lower() for s in p.split(os.sep)]\n    if \"benign\" in parts: files.append(p); labels.append(0)\n    elif \"malignant\" in parts: files.append(p); labels.append(1)\nlabels = np.array(labels)\nprint(f\"{len(files)} images | benign={np.sum(labels==0)} malignant={np.sum(labels==1)}\")\nassert len(files) > 0, \"No images found: inspect folder layout under `path`.\"\n\n# Group near-duplicates (perceptual hash) so they never straddle train/test\nhashes = [imagehash.phash(Image.open(f).convert(\"L\")) for f in files]\ngroups, reps = np.zeros(len(files), int), []\nfor i, h in enumerate(hashes):\n    for g, r in enumerate(reps):\n        if h - r <= 4: groups[i] = g; break\n    else: reps.append(h); groups[i] = len(reps) - 1\nprint(\"duplicate groups:\", len(reps), \"of\", len(files))\n\n# Split ~70/15/15 by group, stratified\nsgkf = StratifiedGroupKFold(n_splits=7, shuffle=True, random_state=SEED)\nfolds = [te for _, te in sgkf.split(files, labels, groups)]\ntest_idx, val_idx = folds[0], folds[1]\ntrain_idx = np.concatenate(folds[2:])\n\nnorm = T.Normalize([0.485,0.456,0.406],[0.229,0.224,0.225])\ntr_tf = T.Compose([T.Resize((224,224)), T.RandomHorizontalFlip(), T.RandomRotation(10),\n                   T.ColorJitter(0.2,0.2), T.ToTensor(), norm])\nev_tf = T.Compose([T.Resize((224,224)), T.ToTensor(), norm])\n\nclass DS(Dataset):\n    def __init__(s, idx, tf): s.idx, s.tf = idx, tf\n    def __len__(s): return len(s.idx)\n    def __getitem__(s, i):\n        j = s.idx[i]\n        return s.tf(Image.open(files[j]).convert(\"RGB\")), int(labels[j])\n\nmk = lambda idx, tf, sh: DataLoader(DS(idx, tf), batch_size=BS, shuffle=sh, num_workers=2)\ntr_dl, va_dl, te_dl = mk(train_idx, tr_tf, True), mk(val_idx, ev_tf, False), mk(test_idx, ev_tf, False)\n\nmodel = models.densenet121(weights=models.DenseNet121_Weights.IMAGENET1K_V1)\nmodel.classifier = nn.Linear(model.classifier.in_features, 2)\nmodel.to(dev)\nw = torch.tensor(len(train_idx) / (2 * np.bincount(labels[train_idx])), dtype=torch.float).to(dev)\ncrit = nn.CrossEntropyLoss(weight=w)\nopt = torch.optim.AdamW(model.parameters(), lr=LR, weight_decay=1e-4)\nsched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, EPOCHS)\n\n@torch.no_grad()\ndef predict(dl):\n    model.eval(); P, Y = [], []\n    for x, y in dl:\n        P.append(torch.softmax(model(x.to(dev)), 1)[:, 1].cpu().numpy()); Y.append(y.numpy())\n    return np.concatenate(P), np.concatenate(Y)\n\nbest_auc, best_state = 0, None\nfor ep in range(EPOCHS):\n    model.train(); tot = 0\n    for x, y in tr_dl:\n        x, y = x.to(dev), y.to(dev)\n        opt.zero_grad(); loss = crit(model(x), y); loss.backward(); opt.step(); tot += loss.item() * len(y)\n    sched.step()\n    p, y = predict(va_dl); auc = roc_auc_score(y, p)\n    print(f\"epoch {ep+1:02d} loss {tot/len(train_idx):.4f} val AUC {auc:.4f}\")\n    if auc > best_auc: best_auc, best_state = auc, {k: v.clone() for k, v in model.state_dict().items()}\n\nmodel.load_state_dict(best_state)\np, y = predict(te_dl)\npred = (p >= 0.5).astype(int)\nprint(\"\\nTEST AUC: %.4f | accuracy: %.4f\" % (roc_auc_score(y, p), (pred == y).mean()))\nprint(confusion_matrix(y, pred))\nprint(classification_report(y, pred, target_names=[\"benign\", \"malignant\"]))\ntn, fp, fn, tp = confusion_matrix(y, pred).ravel()\nprint(f\"Malignant sensitivity: {tp/(tp+fn):.3f} | specificity: {tn/(tn+fp):.3f}\")\ntorch.save(best_state, \"busi_densenet121.pt\")","metadata":{"trusted":true},"outputs":[],"execution_count":null}]}